// Godrank muscle map: Liftoff-style puzzle pieces. Every muscle is its own solid piece with a thin even seam,
// head/hands/feet stay neutral. Shapes live in anatomy-shapes.js (generated by tools/musclemap.py),
// in the pixel space of assets/anatomy.jpg (1712x1152); front figure centered on x=516, back on x=1178.
(()=>{
// muscle groups used by the app -> anatomy regions (each region may hold several pieces, e.g. every ab block)
const GROUP={chest:['F.chest'],shoulders:['F.shoulders','B.shoulders'],traps:['F.traps','B.traps'],biceps:['F.biceps'],triceps:['B.triceps'],
  forearms:['F.forearms','B.forearms'],core:['F.core','F.obliques'],back:['B.back','B.lowerback'],glutes:['B.glutes'],quads:['F.quads'],hams:['B.hams'],calves:['F.calves','B.calves']};
window.MUSCLE_NAMES={chest:'Chest',shoulders:'Shoulders',traps:'Traps',biceps:'Biceps',triceps:'Triceps',forearms:'Forearms',core:'Core',back:'Back',glutes:'Glutes',quads:'Quads',hams:'Hamstrings',calves:'Calves'};
window.MUSCLES=Object.keys(GROUP);
const REGIONS={F:['traps','shoulders','chest','biceps','forearms','core','obliques','quads','calves'],
               B:['traps','shoulders','back','lowerback','triceps','forearms','glutes','hams','calves']};
const NEUTRAL='#c9ccd3', UNRANKED='#8d929b';
let uid=0;
// grey-ish rank colors (Sword God silver) would read as "unranked": tint them steel blue so they still read as colored
const vivid=h=>{const c=[1,3,5].map(i=>parseInt(h.slice(i,i+2),16)),mx=Math.max(...c),mn=Math.min(...c);
  if(mx-mn>40)return h;return '#'+c.map((v,i)=>Math.round(v*.45+[110,160,235][i]*.55).toString(16).padStart(2,'0')).join('')};
// viewBox zoomed onto one muscle group (used for the muscle filter tiles)
function focusBox(g){const rs=GROUP[g]||[];const front=rs.some(r=>r.startsWith('F.'));const pre=front?'F.':'B.';
  const bx=rs.filter(r=>r.startsWith(pre)).map(r=>(window.MUSCLE_BOX||{})[r]).filter(Boolean);if(!bx.length)return null;
  const x0=Math.min(...bx.map(b=>b[0])),y0=Math.min(...bx.map(b=>b[1])),x1=Math.max(...bx.map(b=>b[2])),y1=Math.max(...bx.map(b=>b[3]));
  const s=Math.max(x1-x0,y1-y0)*1.2+30,cx=(x0+x1)/2,cy=(y0+y1)/2;return {vb:`${cx-s/2} ${cy-s/2} ${s} ${s}`,view:front?'front':'back'}}
// colorOf(group) -> rank hex or null; glow: Set of groups to pulse; view: 'both'|'front'|'back'; focus: group to zoom on
window.anatomy=function({colorOf=()=>null,glow=new Set(),view='both',height=360,focus=null}={}){
  const id='an'+(uid++);const fb=focus&&focusBox(focus);if(fb)view=fb.view;
  const vb=fb?fb.vb:view==='front'?'291 30 450 1090':view==='back'?'953 30 450 1090':'291 30 1112 1090';
  const SH=window.MUSCLE_SHAPES||{};
  const fig=k=>{
    let s=SH[k+'.body']?`<path d="${SH[k+'.body']}" fill="${NEUTRAL}"/>`:'',hi='';
    for(const r of REGIONS[k]){const d=SH[k+'.'+r];if(!d)continue;
      const g=Object.keys(GROUP).find(m=>GROUP[m].includes(k+'.'+r));
      const c=g&&colorOf(g);s+=`<path d="${d}" fill="${c?vivid(c):UNRANKED}"/>`;
      if(g&&glow.has(g))hi+=`<path d="${d}" fill="#bfe4ff" fill-opacity=".22" stroke="#7cc4ff" stroke-width="7" stroke-linejoin="round" filter="url(#${id}g)"><animate attributeName="opacity" values=".35;1;.35" dur="1.8s" repeatCount="indefinite"/></path><path d="${d}" fill="none" stroke="#e6f4ff" stroke-width="2.5" stroke-opacity=".9" stroke-linejoin="round"/>`;}
    // soft top light so the flat pieces read as volume, like Liftoff
    return `<g>${s}</g><g fill="url(#${id}l)" style="pointer-events:none">${(SH[k+'.body']?`<path d="${SH[k+'.body']}"/>`:'')+REGIONS[k].map(r=>SH[k+'.'+r]?`<path d="${SH[k+'.'+r]}"/>`:'').join('')}</g>${hi}`};
  return `<svg viewBox="${vb}" height="${height}" style="display:block;margin:0 auto;max-width:100%" aria-label="Muscle map">
   <defs><filter id="${id}g" x="-20%" y="-20%" width="140%" height="140%"><feGaussianBlur stdDeviation="5"/></filter>
   <linearGradient id="${id}l" x1="0" y1="0" x2=".35" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".16"/><stop offset=".55" stop-color="#fff" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".14"/></linearGradient></defs>
   ${view!=='back'?fig('F'):''}${view!=='front'?fig('B'):''}</svg>`;
};
})();
